1	//! An HLG project's deliverables (spec §11 HD-5, HD-14): which picture an
2	//! export row writes — the HLG master, HDR10 (PQ) or the SDR version — and the
3	//! two refusals that keep a file from carrying a picture it cannot label.
4	//!
5	//! The vocabulary is three words, `hlg`, `pq` and `sdr`, spelled
6	//! `dynamic_range` both as an export override (`export_overrides.rs` reads it)
7	//! and as a recipe option (`recipe_options.rs`), because the two are one
8	//! decision seen from two sides: the export publishes its settings' `color` as
9	//! the recipe option of the key it draws, so the output pass the preview draws
10	//! for Show SDR Version is the one the file is written through.
11	//!
12	//! An SDR project is untouched by all of it: `deliverable` answers `None` for
13	//! every row there, so its settings carry no `color` and its recipes no
14	//! `dynamic_range`, and every SDR file and frame is the text and the bytes it
15	//! was.
16	
17	use crate::export_table::Preset;
18	use crate::model::{CanvasOutput, Project};
19	
20	/// The picture an HLG project's export or frame is drawn as (spec §11 HD-14).
21	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
22	pub enum DynamicRange {
23	    /// The working space itself, BT.2100 HLG: no output pass.
24	    Hlg,
25	    /// HDR10: the HLG display light at 1,000 cd/m² through ST 2084.
26	    Pq,
27	    /// The SDR version (spec §11 HD-4): the inverse of the lift with a
28	    /// shoulder above reference white, encoded Rec. 709.
29	    Sdr,
30	}
31	
32	impl DynamicRange {
33	    /// The word for `text`, or `None` for anything else.
34	    pub fn parse(text: &str) -> Option<DynamicRange> {
35	        match text {
36	            "hlg" => Some(DynamicRange::Hlg),
37	            "pq" => Some(DynamicRange::Pq),
38	            "sdr" => Some(DynamicRange::Sdr),
39	            _ => None,
40	        }
41	    }
42	
43	    /// The word as it is spelled in JSON.
44	    pub fn as_str(self) -> &'static str {
45	        match self {
46	            DynamicRange::Hlg => "hlg",
47	            DynamicRange::Pq => "pq",
48	            DynamicRange::Sdr => "sdr",
49	        }
50	    }
51	}
52	
53	/// The rows that carry an HDR picture (spec §11 HD-5, CX-14, CX-15, CX-16):
54	/// the six HDR rows, each 10-bit for an HDR picture (`vp9_webm` is 8-bit only
55	/// at `sdr`). Every other video row of an HLG project writes the SDR version.
56	pub(crate) const HDR_ROWS: [&str; 6] = [
57	    "hevc_10bit",
58	    "av1",
59	    "av1_webm",
60	    "vp9_webm",
61	    "prores_422",
62	    "prores_4444",
63	];
64	
65	impl Project {
66	    /// What `preset` writes for this project when `asked` was requested
67	    /// (spec §11 HD-14 (c)): `None` for an audio row and for every row of an
68	    /// SDR project (nothing to label), else the resolved picture. An audio row
69	    /// reads the argument and ignores it, as a bitrate on a GIF is; an SDR
70	    /// project takes `sdr` as nothing; `hlg` and `pq` are refused in an SDR
71	    /// project and on a row that is not 10-bit, each in its own sentence.
72	    pub(crate) fn deliverable(
73	        &self,
74	        preset: &Preset,
75	        asked: Option<DynamicRange>,
76	    ) -> Result<Option<DynamicRange>, String> {
77	        if !preset.video {
78	            return Ok(None);
79	        }
80	        let hdr_asked = asked.filter(|range| *range != DynamicRange::Sdr);
81	        if self.canvas.output != CanvasOutput::Hlg {
82	            return match hdr_asked {
83	                Some(range) => Err(format!(
84	                    "dynamic_range \"{}\" needs an HLG project; set_canvas output \"hlg\" first",
85	                    range.as_str()
86	                )),
87	                None => Ok(None),
88	            };
89	        }
90	        if HDR_ROWS.contains(&preset.id) {
91	            return Ok(Some(asked.unwrap_or(DynamicRange::Hlg)));
92	        }
93	        match hdr_asked {
94	            Some(range) => Err(format!(
95	                "{} is 8-bit and writes the SDR version; export dynamic_range \"{}\" as \
96	                 hevc_10bit, av1, av1_webm, vp9_webm, prores_422 or prores_4444",
97	                preset.id,
98	                range.as_str()
99	            )),
100	            None => Ok(Some(DynamicRange::Sdr)),
101	        }
102	    }
103	}
104	//! The stems an audio export writes beside its mix (spec §11 AU-108): which
105	//! timeline tracks each file holds and what it is called. Swift writes them
106	//! (`ExportStems.swift`); this answers only the grouping and the names, so
107	//! the sheet, the `export` tool and the tests read one list.
108	//!
109	//! The rules:
110	//!
111	//! - **Heard.** A timeline track is heard when the plan has an audio track
112	//!   labelled with it (`CompTrack::track`, AU-107 — so a track holding only
113	//!   pictures, or nothing, is not) and it is not `silenced` among the
114	//!   timeline's tracks (mute, solo). None heard is refused.
115	//! - **Grouping.** `tracks`: one stem per heard track. `names`: heard tracks
116	//!   whose trimmed names match case-insensitively are one stem, named by the
117	//!   first's spelling; an unnamed track is its own.
118	//! - **Order.** Timeline order of each stem's first track; a stem's tracks
119	//!   in timeline order.
120	//! - **Names.** The trimmed track name, else `Track N` (N = its index + 1,
121	//!   the header's label), with `/` and `:` replaced by `-`; a name equal
122	//!   case-insensitively to an earlier stem's gets ` (Track N)` of its first
123	//!   track, and one still equal to an earlier stem's then gets
124	//!   ` (Track N, 2)`, ` (Track N, 3)` and on, the first no earlier stem
125	//!   holds, so no two stems share a file.
126	
127	use std::collections::BTreeSet;
128	
129	use serde_json::{Map, Value};
130	
131	use crate::audio::silenced;
132	use crate::export_overrides::StemsMode;
133	use crate::model::Project;
134	
135	/// One stem: the file's name (without the mix's) and the timeline tracks
136	/// whose sound it holds.
137	#[derive(Debug, Clone, PartialEq, Eq)]
138	pub(crate) struct Stem {
139	    pub(crate) name: String,
140	    pub(crate) tracks: Vec<u32>,
141	}
142	
143	impl Stem {
144	    /// `{"name": …, "tracks": [ids]}`, the settings' `stems` entry.
145	    pub(crate) fn to_json(&self) -> Value {
146	        let mut out = Map::new();
147	        out.insert("name".to_string(), Value::from(self.name.clone()));
148	        let tracks = self.tracks.iter().map(|id| Value::from(*id)).collect();
149	        out.insert("tracks".to_string(), Value::Array(tracks));
150	        Value::Object(out)
151	    }
152	}
153	
154	/// A group while it is being gathered: its first track's index and the
155	/// spelling it is named by.
156	struct Group {
157	    first: usize,
158	    spelling: String,
159	    tracks: Vec<u32>,
160	}
161	
162	impl Project {
163	    /// The stems `mode` asks for, in order (spec §11 AU-108 (b), (c)), or
164	    /// the refusal when no track is heard.
165	    pub(crate) fn export_stems(&self, mode: StemsMode) -> Result<Vec<Stem>, String> {
166	        let labelled: BTreeSet<u32> = self.assign().audio.iter().map(|t| t.track).collect();
167	        let mut groups: Vec<Group> = Vec::new();
168	        for (index, track) in self.tracks.iter().enumerate() {
169	            if !labelled.contains(&track.id) || silenced(&self.tracks, track) {
170	                continue;
171	            }
172	            let trimmed = track.name.trim();
173	            let joins = match mode {
174	                StemsMode::Tracks => None,
175	                StemsMode::Names if trimmed.is_empty() => None,
176	                StemsMode::Names => groups
177	                    .iter_mut()
178	                    .find(|g| !g.spelling.is_empty() && same(&g.spelling, trimmed)),
179	            };
180	            match joins {
181	                Some(group) => group.tracks.push(track.id),
182	                None => groups.push(Group {
183	                    first: index,
184	                    spelling: trimmed.to_string(),
185	                    tracks: vec![track.id],
186	                }),
187	            }
188	        }
189	        if groups.is_empty() {
190	            return Err("stems: no track is heard, so there is no stem to write".to_string());
191	        }
192	        let mut stems: Vec<Stem> = Vec::with_capacity(groups.len());
193	        for group in groups {
194	            let label = format!("Track {}", group.first.saturating_add(1));
195	            let base = if group.spelling.is_empty() {
196	                label.clone()
197	            } else {
198	                group.spelling.replace(['/', ':'], "-")
199	            };
200	            let taken = |name: &str| stems.iter().any(|s| same(&s.name, name));
201	            let mut name = base.clone();
202	            if taken(&name) {
203	                name = format!("{base} ({label})");
204	            }
205	            let mut count: u32 = 2;
206	            while taken(&name) {
207	                name = format!("{base} ({label}, {count})");
208	                count = count.saturating_add(1);
209	            }
210	            stems.push(Stem {
211	                name,
212	                tracks: group.tracks,
213	            });
214	        }
215	        Ok(stems)
216	    }
217	}
218	
219	/// Two names the same but for case.
220	fn same(a: &str, b: &str) -> bool {
221	    a.to_lowercase() == b.to_lowercase()
222	}
223	//! The containers Frame Job writes (spec §7.8), and the four questions
224	//! each one answers about ITSELF: its extension, its UTI, whether a
225	//! leading index is worth rewriting, whether it can hold sound at all.
226	//!
227	//! Moved whole out of `export_table.rs` under the size rule (core/CLAUDE.md:
228	//! a module at ~600 lines gives something up BEFORE it takes anything on),
229	//! as codec-export C1's toll T1, a pure move. `export_table.rs` re-exports
230	//! [`Container`], so every `crate::export_table::Container` path holds.
231	
232	/// The containers Frame Job writes. Kept as an enum rather than a string so
233	/// the container, its UTI, its network-optimization default and whether it
234	/// can hold sound at all are decided in exactly one exhaustive place.
235	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
236	pub(crate) enum Container {
237	    Mov,
238	    Mp4,
239	    M4a,
240	    Wav,
241	    Aiff,
242	    Gif,
243	    Apng,
244	    /// WebM, written by the core's own writer (`webm_writer.rs`, spec §11
245	    /// CX-15), not by AVFoundation.
246	    Webm,
247	}
248	
249	impl Container {
250	    pub(crate) fn as_str(self) -> &'static str {
251	        match self {
252	            Container::Mov => "mov",
253	            Container::Mp4 => "mp4",
254	            Container::M4a => "m4a",
255	            Container::Wav => "wav",
256	            Container::Aiff => "aiff",
257	            Container::Gif => "gif",
258	            Container::Apng => "apng",
259	            Container::Webm => "webm",
260	        }
261	    }
262	
263	    /// The output file's UTI. On the AVFoundation path Swift passes this
264	    /// straight to `outputFileType`, whose raw values ARE UTIs; on the
265	    /// ImageIO path it is the destination type
266	    /// `CGImageDestinationCreateWithURL` takes. Either way it is what the
267	    /// save panel's content type and file extension are derived from, which
268	    /// is why the two image formats name a real UTI here rather than
269	    /// nothing — an export that could not tell the panel it writes a `.gif`
270	    /// would be worse off than one whose type string a session would
271	    /// reject, and a session is never built for them.
272	    ///
273	    /// An APNG is written to an ordinary PNG destination — the animation
274	    /// lives in `acTL`/`fcTL` chunks inside a file that is still a PNG — so
275	    /// its type identifier is PNG's, not one of its own.
276	    ///
277	    /// The two LPCM rows' identifiers are exactly `AVFileType.wav` and
278	    /// `AVFileType.aiff`'s raw values, which is what lets
279	    /// `Exporter.fileType(for:)` resolve them from this string alone
280	    /// rather than growing a container list of its own.
281	    pub(crate) fn file_type(self) -> &'static str {
282	        match self {
283	            Container::Mov => "com.apple.quicktime-movie",
284	            Container::Mp4 => "public.mpeg-4",
285	            Container::M4a => "com.apple.m4a-audio",
286	            Container::Wav => "com.microsoft.waveform-audio",
287	            Container::Aiff => "public.aiff-audio",
288	            Container::Gif => "com.compuserve.gif",
289	            Container::Apng => "public.png",
290	            Container::Webm => "org.webmproject.webm",
291	        }
292	    }
293	
294	    /// Whether `shouldOptimizeForNetworkUse` defaults on. MP4 and M4A are
295	    /// the delivery containers people upload, and a leading `moov` atom
296	    /// lets a player start before the file is fully fetched. A ProRes MOV
297	    /// is an editing master handed to another application, where the
298	    /// rewrite pass buys nothing. An HEVC-with-alpha MOV is a delivery file
299	    /// too, and its default stays off all the same: that was the owner's
300	    /// choice for the row (spec §11 G-33), and the override turns it on. GIF
301	    /// and APNG have no `moov` atom and nothing to move: a viewer already
302	    /// starts on the first frame, and
303	    /// neither do WAV and AIFF — a RIFF or an IFF file is a header
304	    /// followed by samples, with no index to relocate, so the flag would
305	    /// be a request the writer has nothing to do about. A WebM's index (its
306	    /// SeekHead) is already at the front, so the flag is off and inert there
307	    /// too (spec §11 CX-15 (1)).
308	    pub(crate) fn optimizes_for_network(self) -> bool {
309	        matches!(self, Container::Mp4 | Container::M4a)
310	    }
311	
312	    /// Whether the container can hold sound. Every movie container can,
313	    /// and M4A, WAV and AIFF are nothing else; GIF and APNG are picture
314	    /// formats with no audio track in the file format at all, so
315	    /// `audio: false` for those is a fact about the container rather than
316	    /// a decision about the project.
317	    pub(crate) fn carries_audio(self) -> bool {
318	        !matches!(self, Container::Gif | Container::Apng)
319	    }
320	}
321	//! The bundled encoders a row's video can take (spec §11 CX-12): the route,
322	//! [`Writer`], and the speed vocabulary, [`EncoderSpeed`].
323	//!
324	//! Moved whole out of `export_table.rs` under the size rule (core/CLAUDE.md:
325	//! a module at ~600 lines gives something up BEFORE it takes anything on),
326	//! as codec-export C3's toll T1, a pure move. `export_table.rs` re-exports
327	//! both, so every `crate::export_table::Writer` and
328	//! `crate::export_table::EncoderSpeed` path holds.
329	
330	/// The route a row's video takes when it is not AVFoundation's own
331	/// encoder (spec §11 CX-12 (1)): `None` on a row means VideoToolbox or
332	/// ProRes through `AVAssetWriter`, or ImageIO where `avf_preset` is null.
333	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
334	pub(crate) enum Writer {
335	    /// SVT-AV1, bundled and called from Swift (CX-2, CX-4).
336	    SvtAv1,
337	    /// libvpx's VP9, bundled and called from Swift (CX-3, CX-4, CX-16).
338	    Libvpx,
339	}
340	
341	impl Writer {
342	    pub(crate) fn as_str(self) -> &'static str {
343	        match self {
344	            Writer::SvtAv1 => "svt_av1",
345	            Writer::Libvpx => "libvpx",
346	        }
347	    }
348	
349	    /// Whether the encoder has speeds to choose from: SVT-AV1's three
350	    /// (CX-2), and not libvpx's one (CX-3, CX-16 (2)).
351	    pub(crate) fn takes_speed(self) -> bool {
352	        match self {
353	            Writer::SvtAv1 => true,
354	            Writer::Libvpx => false,
355	        }
356	    }
357	}
358	
359	/// A bundled encoder's speed (spec §11 CX-2, CX-12 (2)): Faster, Balanced
360	/// and Smaller file are SVT-AV1's presets 8, 6 and 4 — the number is the
361	/// app's to map, the word is the vocabulary the sheet and `export` share.
362	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
363	pub(crate) enum EncoderSpeed {
364	    Faster,
365	    Balanced,
366	    Smaller,
367	}
368	
369	impl EncoderSpeed {
370	    /// Every speed, in the sheet's order.
371	    pub(crate) const ALL: [EncoderSpeed; 3] = [
372	        EncoderSpeed::Faster,
373	        EncoderSpeed::Balanced,
374	        EncoderSpeed::Smaller,
375	    ];
376	
377	    pub(crate) fn parse(text: &str) -> Option<Self> {
378	        Self::ALL.into_iter().find(|speed| speed.as_str() == text)
379	    }
380	
381	    pub(crate) fn as_str(self) -> &'static str {
382	        match self {
383	            EncoderSpeed::Faster => "faster",
384	            EncoderSpeed::Balanced => "balanced",
385	            EncoderSpeed::Smaller => "smaller",
386	        }
387	    }
388	}
389	import AVFoundation
390	
391	/// An audio export's stems (spec §11 AU-108): the mix, then one file per stem
392	/// beside it, in one job. `Exporter.pipeline` wraps the mix's `ExportWriter`
393	/// in this when the settings carry `stems`, and it is otherwise the one
394	/// pipeline it was.
395	///
396	/// **Each stem is its own write** (spec §11 #378, CX-15 (2)): a fresh build of
397	/// the same plan on the export's key — fresh taps, for `ExporterLoudness`'s
398	/// reason, and the ramp, isolation and voice renders the key holds — read
399	/// through only its own composition tracks (`BuiltComposition.selectingAudio`)
400	/// into an `ExportWriter` of its own, whose master neither gains nor limits
401	/// (`ExportAudioMaster(limits: false)`): a stem is pre-master, so the stems
402	/// sum to the mix within rounding wherever the master neither gains nor
403	/// limits. The builds run on this pipeline's one serial queue; each writer is
404	/// made and started on the main thread, and the job's completion, the last
405	/// stem's, precedes `Exporter.finish`, which releases the key.
406	///
407	/// **Nothing is left by a failure or a cancel**: the mix and every stem that
408	/// finished are removed here, and the part-written one by its writer.
409	///
410	/// **The names** are the core's (`export_stems.rs`); a stem's file is
411	/// `<mix name> - <stem name>.<mix extension>` beside the mix, replacing a file
412	/// there without asking — except one of the project's media, which refuses
413	/// the job before any stem file is touched (`collision`, `SourceCollision`).
414	final class ExportStemsPipeline: ExportPipeline, ExportAudioNormalizing {
415	
416	    /// A stem's path names media the project uses (spec §11 AU-108 (d)).
417	    struct SourceCollision: LocalizedError {
418	        let url: URL
419	        var errorDescription: String? {
420	            "The stem “\(url.lastPathComponent)” would replace media this project uses; "
421	                + "export under another name."
422	        }
423	    }
424	
425	    private let mix: ExportWriter
426	    private let stems: [ExportStem]
427	    private let settings: ExportSettings
428	    private let mixURL: URL
429	    private let rebuild: () throws -> BuiltComposition
430	    /// The stems' builds, one at a time.
431	    private let queue = DispatchQueue(
432	        label: "com.kgalligan.framejob.export.stems", qos: .userInitiated)
433	
434	    /// Guards everything `progress` and `cancel` read off the main thread.
435	    private let lock = NSLock()
436	    /// The write running now (the mix first), nil between two.
437	    private var current: ExportWriter?
438	    /// Writes finished, the mix included.
439	    private var finishedCount = 0
440	    private var cancelRequested = false
441	    /// Files this job finished, removed if it does not end well. Main thread.
442	    private var written: [URL] = []
443	    /// Called once, on the main thread, and then dropped.
444	    private var completion: ((Result<URL, any Error>) -> Void)?
445	
446	    init(
447	        mix: ExportWriter, stems: [ExportStem], settings: ExportSettings, mixURL: URL,
448	        sources: [URL], rebuild: @escaping () throws -> BuiltComposition
449	    ) throws {
450	        if let clash = Self.collision(stems: stems, mix: mixURL, sources: sources) {
451	            throw SourceCollision(url: clash)
452	        }
453	        self.mix = mix
454	        self.stems = stems
455	        self.settings = settings
456	        self.mixURL = mixURL
457	        self.rebuild = rebuild
458	        current = mix
459	    }
460	
461	    // MARK: - Names
462	
463	    /// `<mix name without extension> - <stem name>.<mix extension>`, beside
464	    /// the mix.
465	    static func url(for stem: ExportStem, mix: URL) -> URL {
466	        let base = mix.deletingPathExtension().lastPathComponent
467	        let ext = mix.pathExtension
468	        let file = ext.isEmpty ? "\(base) - \(stem.name)" : "\(base) - \(stem.name).\(ext)"
469	        return mix.deletingLastPathComponent().appendingPathComponent(file)
470	    }
471	
472	    /// The success line's tail: "", " and 1 stem" or " and N stems".
473	    static func summary(_ settings: ExportSettings) -> String {
474	        switch settings.stems.count {
475	        case 0: return ""
476	        case 1: return " and 1 stem"
477	        case let count: return " and \(count) stems"
478	        }
479	    }
480	
481	    /// The first stem URL that is one of `sources` — symlinks resolved,
482	    /// standardized, compared case-insensitively — or nil.
483	    static func collision(stems: [ExportStem], mix: URL, sources: [URL]) -> URL? {
484	        let taken = Set(sources.map(canonical))
485	        return stems.map { url(for: $0, mix: mix) }.first { taken.contains(canonical($0)) }
486	    }
487	
488	    private static func canonical(_ url: URL) -> String {
489	        url.resolvingSymlinksInPath().standardizedFileURL.path.lowercased()
490	    }
491	
492	    // MARK: - The pipeline
493	
494	    /// The mix's share first, then each stem's: `(finished + current) / (1 + N)`.
495	    var progress: Double {
496	        lock.lock()
497	        defer { lock.unlock() }
498	        let running = current?.progress ?? 0
499	        return (Double(finishedCount) + running) / Double(1 + stems.count)
500	    }
501	
502	    /// The loudness gain is the mix's alone (spec §11 AU-108 (e)).
503	    func normalizeAudio(byLinearGain gain: Float) {
504	        mix.normalizeAudio(byLinearGain: gain)
505	    }
506	
507	    func start(completion: @escaping (Result<URL, any Error>) -> Void) {
508	        self.completion = completion
509	        mix.start { [weak self] result in self?.ended(result, at: self?.mixURL, next: 0) }
510	    }
511	
512	    /// Sets the flag and stops the write running now; a stem not yet started
513	    /// sees the flag before it starts.
514	    func cancel() {
515	        lock.lock()
516	        cancelRequested = true
517	        let running = current
518	        lock.unlock()
519	        running?.cancel()
520	    }
521	
522	    private var isCancelled: Bool {
523	        lock.lock()
524	        defer { lock.unlock() }
525	        return cancelRequested
526	    }
527	
528	    /// One write ended (main thread): on success the file is kept and stem
529	    /// `next` follows; otherwise the job ends with nothing left behind.
530	    private func ended(_ result: Result<URL, any Error>, at url: URL?, next: Int) {
531	        lock.lock()
532	        current = nil
533	        lock.unlock()
534	        switch result {
535	        case .failure(let error):
536	            if let url { written.append(url) }
537	            fail(error)
538	        case .success:
539	            if let url { written.append(url) }
540	            lock.lock()
541	            finishedCount += 1
542	            lock.unlock()
543	            write(next)
544	        }
545	    }
546	
547	    /// Builds stem `index` on the queue, then writes it on the main thread.
548	    private func write(_ index: Int) {
549	        guard !isCancelled else { return fail(Exporter.ExportError.cancelled) }
550	        guard index < stems.count else { return complete(.success(mixURL)) }
551	        let stem = stems[index]
552	        queue.async { [weak self] in
553	            guard let self else { return }
554	            let built = Result { try self.rebuild().selectingAudio(of: Set(stem.tracks)) }
555	            DispatchQueue.main.async { self.writeBuilt(built, stem: stem, index: index) }
556	        }
557	    }
558	
559	    private func writeBuilt(_ built: Result<BuiltComposition, any Error>, stem: ExportStem, index: Int) {
560	        guard !isCancelled else { return fail(Exporter.ExportError.cancelled) }
561	        let url = Self.url(for: stem, mix: mixURL)
562	        let writer: ExportWriter
563	        do {
564	            let composition = try built.get()
565	            // The save panel asked about the mix; a stem's file is replaced.
566	            try? FileManager.default.removeItem(at: url)
567	            writer = try ExportWriter(built: composition, settings: settings, chapters: [], to: url)
568	        } catch {
569	            return fail(error)
570	        }
571	        lock.lock()
572	        current = writer
573	        let cancelled = cancelRequested
574	        lock.unlock()
575	        if cancelled { writer.cancel() }
576	        writer.start { [weak self] result in self?.ended(result, at: url, next: index + 1) }
577	    }
578	
579	    /// Removes every file this job wrote, then reports `error`.
580	    private func fail(_ error: any Error) {
581	        for url in written { try? FileManager.default.removeItem(at: url) }
582	        written = []
583	        complete(.failure(error))
584	    }
585	
586	    private func complete(_ result: Result<URL, any Error>) {
587	        let handler = completion
588	        completion = nil
589	        handler?(result)
590	    }
591	}
