808	/// Pass one of an export: read the composed mix and MEASURE it (`Loudness.swift`).
809	///
810	/// This is `Exporter`'s own "Measuring the mix" section, in a file of its own
811	/// because `Exporter.swift` went past app/CLAUDE.md's ~600-line cap when phase
812	/// 5 put a second pass in it. It is a MOVE and nothing else — the same methods,
813	/// the same order, the same bodies — so `Exporter.swift`'s five internal members
814	/// (`lock`, `measuring`, `scratchStorage`, `scratchCapacity`, and the
815	/// `isCancelled` / `setMeasureProgress` accessors over that lock) are internal
816	/// only to be reachable from here. Stored properties cannot live in an
817	/// extension, which is the whole reason the split is where it is.
818	///
819	/// **What it buys.** Every export that carries sound gets a measured
820	/// "Peak −1.0 dBTP · −14.0 LUFS" on its final line, and an export that asked to
821	/// be normalised gets the gain that lands it on its target. The pass is a
822	/// reader with no writer, no video output and no encoder — audio decode through
823	/// the plan's own mix, and nothing else — so it costs a few per cent of a movie
824	/// export and roughly doubles an audio-only one, which is also the case where
825	/// the number matters most.
826	///
827	/// **It builds its OWN composition.** An `AVAudioMix` copy shares the
828	/// `MTAudioProcessingTap` objects its input parameters hold, and a tap carries
829	/// per-instance state (the compressor's envelope, the noise reducer's delay
830	/// line), so two readers over one mix would interleave into one tap's. Running
831	/// them strictly in sequence would *probably* survive on `AudioTapContext`'s
832	/// start-of-stream reset — but not for a range shorter than its 0.1 s seek
833	/// tolerance, and a second build costs one more pass of opening asset tracks on
834	/// a queue that exists for exactly that and removes the argument entirely. It is
835	/// the same movie by construction: the same plan JSON, the same media, the same
836	/// recipe slot. Its `videoComposition` is never read. `Exporter.export` is where
837	/// that second build happens; everything below is what it is handed.
838	///
839	/// **Nothing here can fail an export.** Every refusal is a nil, which means "no
840	/// loudness figure" and never "no file": the write pass that follows is the one
841	/// that decides whether there is one.
842	extension Exporter {
843	
844	    // MARK: - Measuring the mix
845	
846	    /// What the measurement READS: `ExportAudioMaster.floatMixSettings`, the
847	    /// one float dictionary, and the same one every export's write pass reads
848	    /// (spec §11 #86, AU-27). So the gain is applied to exactly the signal
849	    /// measured here, and the master limits it.
850	    ///
851	    /// **Why float.** Int16 SATURATES. A mix hotter than full scale — which
852	    /// is exactly the material loudness normalisation exists for — would be
853	    /// measured clipped, and its true peak would be pinned at 0 dBTP by the
854	    /// decode rather than by the signal. Read as float, the overshoot is
855	    /// measured whole and the master holds it at its ceiling.
856	    ///
857	    /// **Why the rate and the channel count are the writer's.** BS.1770-4
858	    /// sums weighted channel powers and left and right both carry 1.0, so
859	    /// the same signal measured as one channel and written as two is 3.01 LU
860	    /// apart. An `AVAssetReaderAudioMixOutput` will happily give one channel
861	    /// to a caller who asks; measuring at a shape the file is not written at
862	    /// is a silent 3 dB error.
863	    private static let measureSampleRate: Double = 48000
864	    private static let measureChannelCount = 2
865	    private static let measureAudioSettings = ExportAudioMaster.floatMixSettings
866	
867	    /// The same, in the writer's own 16-bit integer. Nothing in this tree had
868	    /// asked an `AVAssetReaderAudioMixOutput` for float before phase 5, so
869	    /// the float request is MEASURED with `canAdd` rather than assumed and
870	    /// this is what a refusal falls back to — a measurement of a signal
871	    /// clipped at full scale is still better than no measurement, and the
872	    /// fallback is recorded here rather than discovered as a wrong number.
873	    ///
874	    /// **Measured on macOS 26.5.1: the float request is accepted**
875	    /// (`canAdd` answered true over a composition with one audio track and a
876	    /// mix, and the pass measured EBU Tech 3341 case 1 at −22.994 LUFS
877	    /// against its −23.0). So this dictionary is insurance and not a path
878	    /// anything here has taken; if it ever is taken, the loudness of a mix
879	    /// with no headroom problem is unaffected and the true peak of one that
880	    /// has is pinned at 0 dBTP. A fallback read records no 10 ms steps, so
881	    /// the gain is then the unlimited one (spec §11 AU-28).
882	    private static let measureFallbackAudioSettings: [String: Any] = [
883	        AVFormatIDKey: Int(kAudioFormatLinearPCM),
884	        AVSampleRateKey: 48000,
885	        AVNumberOfChannelsKey: 2,
886	        AVLinearPCMBitDepthKey: 16,
887	        AVLinearPCMIsFloatKey: false,
888	        AVLinearPCMIsBigEndianKey: false,
889	        AVLinearPCMIsNonInterleaved: false,
890	    ]
891	
892	    /// Pass one: read the composed mix and measure it. `buildQueue`, never
893	    /// the main thread.
894	    ///
895	    /// The range is the SETTINGS' — `Exporter.timeRange`, the same one the
896	    /// writer will read — and not the composition's own duration, or the
897	    /// measurement would cover a different span than the file. No video
898	    /// output is added, which is the whole reason the pass is cheap. A float
899	    /// read also feeds `StepLoudnessMeter`, whose 10 ms steps the gain is
900	    /// solved over under the master (spec §11 AU-28).
901	    ///
902	    /// nil for a composition with no sound, for a read this Mac refuses, and
903	    /// for a cancel. A nil is "no loudness figure", never a failed export:
904	    /// the write that follows is the one that decides whether there is a
905	    /// file. A normalisation that was asked for and could not be measured
906	    /// therefore writes UN-normalised, and the missing line on the progress
907	    /// sheet is how that shows — which is honest for the only case that
908	    /// reaches it in practice (a timeline with no sound at all), because
909	    /// every other nil here is a decode failure the write pass runs into a
910	    /// moment later and reports as the error it is.
911	    func measureLoudness(
912	        _ built: BuiltComposition, settings: ExportSettings
913	    ) -> ExportLoudness? {
914	        let tracks = built.composition.tracks(withMediaType: .audio)
915	        guard !tracks.isEmpty, let reader = try? AVAssetReader(asset: built.composition),
916	            let meter = LoudnessMeter(
917	                sampleRate: Exporter.measureSampleRate,
918	                channelCount: Exporter.measureChannelCount)
919	        else { return nil }
920	        let stepMeter = StepLoudnessMeter()
921	        let range = Exporter.timeRange(settings, composition: built.composition)
922	        let seconds = max(0, CMTimeGetSeconds(range.duration))
923	        reader.timeRange = range
924	        // Only the frames the file will hold are measured (spec §11 #337).
925	        let limit = ExportAudioEnd.frames(ofTicks: CompositionBuilder.ticks(range.duration))
926	        var fed = 0
927	
928	        // A build whose tracks have dynamics is measured through their
929	        // sub-mixes (`ExportMixRead`, spec §11 AU-152), float only: there is
930	        // no 16-bit fallback for it.
931	        let mixRead = ExportMixRead(built, origin: range.start)
932	        let subMixed = mixRead.isSubMixed
933	        var isFloat = true
934	        var output = Exporter.mixOutput(tracks, mix: built.audioMix, float: true)
935	        if subMixed {
936	            guard mixRead.add(to: reader) else { return nil }
937	        } else {
938	            if !reader.canAdd(output) {
939	                isFloat = false
940	                output = Exporter.mixOutput(tracks, mix: built.audioMix, float: false)
941	                guard reader.canAdd(output) else { return nil }
942	            }
943	            reader.add(output)
944	        }
945	        guard reader.startReading() else { return nil }
946	        lock.lock()
947	        measuring = true
948	        lock.unlock()
949	        defer {
950	            lock.lock()
951	            measuring = false
952	            lock.unlock()
953	        }
954	
955	        let read = { () -> CMSampleBuffer? in
956	            subMixed ? (try? mixRead.next()) ?? nil : output.copyNextSampleBuffer()
957	        }
958	        while let sample = read() {
959	            guard !isCancelled else {
960	                reader.cancelReading()
961	                return nil
962	            }
963	            fed += feed(
964	                sample, to: meter, steps: isFloat ? stepMeter : nil, float: isFloat,
965	                limit: limit - fed)
966	            guard seconds > 0 else { continue }
967	            let elapsed = CMTimeGetSeconds(
968	                CMSampleBufferGetPresentationTimeStamp(sample) - range.start)
969	            setMeasureProgress(min(max(elapsed / seconds, 0), 1))
970	        }
971	        guard reader.status == .completed else { return nil }
972	        setMeasureProgress(1)
973	        let measuredSteps = isFloat ? stepMeter.finish() : (steps: [], peaks: [])
974	        return ExportLoudness.resolve(
975	            measured: meter.finish(), steps: measuredSteps.steps, peaks: measuredSteps.peaks,
976	            target: settings.loudnessLufs, ceiling: settings.masterCeilingDBTP)
977	    }
