979	    /// One read-only output over the plan's mix — the same taps, the same
980	    /// volume ramps the writer will read through.
981	    private static func mixOutput(
982	        _ tracks: [AVAssetTrack], mix: AVAudioMix?, float: Bool
983	    ) -> AVAssetReaderAudioMixOutput {
984	        let output = AVAssetReaderAudioMixOutput(
985	            audioTracks: tracks,
986	            audioSettings: float ? measureAudioSettings : measureFallbackAudioSettings)
987	        output.audioMix = mix
988	        // Nothing here writes a sample back, so there is no reason to pay
989	        // for a copy of every buffer (`MediaImporter.peaks` is the precedent).
990	        output.alwaysCopiesSampleData = false
991	        return output
992	    }
993	
994	    /// One sample buffer into the meter, and on a float read the step meter
995	    /// too, at most `limit` frames of it; the frames fed.
996	    ///
997	    /// A `CMBlockBuffer` may be several non-contiguous chunks, and
998	    /// `CMBlockBufferGetDataPointer` on the first one silently truncates the
999	    /// buffer — the trap `MediaImporter.peaks` records and
1000	    /// `ReverseRenderer.appendAudioBytes` avoids the same way.
1001	    private func feed(
1002	        _ sample: CMSampleBuffer, to meter: LoudnessMeter, steps: StepLoudnessMeter?,
1003	        float: Bool, limit: Int
1004	    ) -> Int {
1005	        guard limit > 0, let block = CMSampleBufferGetDataBuffer(sample) else { return 0 }
1006	        let width = float ? MemoryLayout<Float>.size : MemoryLayout<Int16>.size
1007	        let frames = min(
1008	            CMBlockBufferGetDataLength(block) / (width * Exporter.measureChannelCount), limit)
1009	        let byteCount = frames * width * Exporter.measureChannelCount
1010	        guard frames > 0, let bytes = scratch(ofAtLeast: byteCount) else { return 0 }
1011	        guard CMBlockBufferCopyDataBytes(
1012	            block, atOffset: 0, dataLength: byteCount, destination: bytes)
1013	            == kCMBlockBufferNoErr
1014	        else { return 0 }
1015	        if float {
1016	            let floats = bytes.bindMemory(to: Float.self, capacity: byteCount / width)
1017	            meter.feed(floats, frames: frames)
1018	            steps?.feed(floats, frames: frames)
1019	        } else {
1020	            meter.feedInt16(
1021	                bytes.bindMemory(to: Int16.self, capacity: byteCount / width), frames: frames)
1022	        }
1023	        return frames
1024	    }
1025	
1026	    private func scratch(ofAtLeast bytes: Int) -> UnsafeMutableRawPointer? {
1027	        if scratchCapacity < bytes {
1028	            scratchStorage?.deallocate()
1029	            scratchStorage = .allocate(byteCount: bytes, alignment: 16)
1030	            scratchCapacity = bytes
1031	        }
1032	        return scratchStorage
1033	    }
1034	}
