1037	// The arithmetic that turns a loudness measurement into an export gain: a pure move out of
1038	// `Loudness.swift` (road map "audio" AP0's toll T3), which keeps the BS.1770-4 meter and the
1039	// `LoudnessReport` it answers.
1040	
1041	// MARK: - What an export did about it
1042	
1043	/// A measurement, the target it was measured against, and the gain that
1044	/// follows — the value both consumers of an export read (the progress
1045	/// sheet's final line and the `export` tool's result).
1046	///
1047	/// **The gain is applied under a master limiter** (spec §11 AU-27, AU-28):
1048	/// every export with sound runs `ExportAudioMaster` — the gain, then
1049	/// `AudioLimiterStage` at the export's ceiling — so the gain that reaches a
1050	/// target is solved through `AudioLimiterModel` over pass one's 10 ms steps,
1051	/// the model the clip limiter's Normalize already uses (AU-24). A scalar gain
1052	/// shifts the true peak by itself, and the master holds what passes the
1053	/// ceiling there, so the file's true peak is `min(measured + gain, ceiling)`
1054	/// and what the master took off is `limitedDB`. Nothing clips any more.
1055	///
1056	/// This file stays free of AVFoundation and AppKit: `phase5_chrome.py` §9
1057	/// compiles it with `Loudness.swift`, `StepLoudness.swift` and
1058	/// `AudioLimiterModel.swift` alone.
1059	struct ExportLoudness: Equatable {
1060	    /// What the mix measured, before any gain.
1061	    let measured: LoudnessReport
1062	    /// The integrated target that was asked for, or nil when the export was
1063	    /// not normalised at all and this is a readout.
1064	    let target: Double?
1065	    /// The master limiter's true-peak ceiling, dBTP.
1066	    let ceiling: Double
1067	    /// The gain that was applied, in dB. Quantised (see `gainStepDB`), and
1068	    /// exactly 0 when nothing was applied.
1069	    let gainDB: Double
1070	    /// What the file holds, LUFS: the model's figure at `gainDB` under the
1071	    /// master (AU-28), else the measurement shifted by the gain; nil when
1072	    /// gated out.
1073	    let integratedLUFS: Double?
1074	    /// True when the +40 dB cap, not the target, decided the gain — the case
1075	    /// worth reporting, because the file will then be quieter than asked.
1076	    let cappedByGain: Bool
1077	
1078	    /// The master's ceiling when a caller names none: AU-4's −1 dBTP, for
1079	    /// normalised and un-normalised exports alike (AU-27).
1080	    static let defaultCeiling: Double = -1
1081	
1082	    /// The most gain a target may ask for, dB.
1083	    static let maxGainDB: Double = 40
1084	
1085	    /// The master limiter's release, seconds (AU-27): `ExportAudioMaster`'s,
1086	    /// spelled here so the model and the stage read one number.
1087	    static let masterReleaseSeconds = 0.1
1088	
1089	    /// The fewest 10 ms steps the model is run over: one 400 ms gating block.
1090	    private static let modelSteps = 40
1091	
1092	    /// The grid the applied gain is rounded to, in dB — to NEAREST (AU-28):
1093	    /// the limiter holds the ceiling, so no rounding has to lean toward it.
1094	    ///
1095	    /// Not cosmetic. AVFoundation's mix is not bit-deterministic near a duck
1096	    /// ramp edge (CLAUDE.md records 38 samples of one 16-bit LSB), which
1097	    /// moves the measured loudness by something like 10⁻⁵ LU — irrelevant to
1098	    /// a ±0.5 LU target, but enough that a raw `Double` gain would differ in
1099	    /// its last bits between two runs and round the ENTIRE file's samples
1100	    /// differently. At 0.01 dB the two runs pick the same gain, so two
1101	    /// normalised exports of one project compare, and "−14.0 LUFS"
1102	    /// reproduces.
1103	    static let gainStepDB: Double = 0.01
1104	
1105	    /// The linear multiplier the master applies to the float mix.
1106	    var linearGain: Double { pow(10, gainDB / 20) }
1107	
1108	    /// True when the master has no gain to apply. It still limits and
1109	    /// quantises.
1110	    var isUnity: Bool { gainDB == 0 }
1111	
1112	    /// The file's true peak: the measurement shifted by the gain, held at the
1113	    /// ceiling. A non-finite measurement passes through unclamped, so the
1114	    /// summary can still say "Silent" (−∞) or that the peak could not be
1115	    /// measured (+∞).
1116	    var truePeakDBTP: Double {
1117	        guard measured.truePeakDBTP.isFinite else { return measured.truePeakDBTP }
1118	        return min(measured.truePeakDBTP + gainDB, ceiling)
1119	    }
1120	
1121	    /// How far the master turned the hottest peak down, dB: the shifted
1122	    /// measurement's excess over the ceiling, 0 when under it or not finite.
1123	    var limitedDB: Double {
1124	        guard measured.truePeakDBTP.isFinite else { return 0 }
1125	        return max(0, measured.truePeakDBTP + gainDB - ceiling)
1126	    }
1127	
1128	    /// The gain a `target` asks for over `measured` and its 10 ms `steps`
1129	    /// (energies) and `peaks` (true peaks, linear) under the master's
1130	    /// `ceiling` (spec §11 AU-28).
1131	    ///
1132	    /// `target` nil is "do not normalise": the measurement is still carried,
1133	    /// and the file's loudness is still the model's, because the master
1134	    /// limits an un-normalised mix that passes the ceiling too.
1135	    ///
1136	    /// A peak that is not a finite number keeps the old handling: no model,
1137	    /// no gain, the measured loudness. −∞ is digital silence; +∞ is float
1138	    /// source media holding a non-finite sample, and "the peak cannot be
1139	    /// measured" has to mean "do not push it up".
1140	    static func resolve(
1141	        measured: LoudnessReport, steps: [Double], peaks: [Double], target: Double?,
1142	        ceiling: Double?
1143	    ) -> ExportLoudness {
1144	        let ceiling = ceiling ?? defaultCeiling
1145	        guard measured.truePeakDBTP.isFinite else {
1146	            return ExportLoudness(
1147	                measured: measured, target: target, ceiling: ceiling, gainDB: 0,
1148	                integratedLUFS: measured.integratedLUFS, cappedByGain: false)
1149	        }
1150	        let linearCeiling = pow(10, ceiling / 20)
1151	        let modelled = steps.count >= modelSteps && StepLoudness.integrated(steps) != nil
1152	        var gainDB = 0.0
1153	        var capped = false
1154	        if let target, let integrated = measured.integratedLUFS {
1155	            let wanted: Double
1156	            if modelled {
1157	                let maxGain = pow(10, maxGainDB / 20)
1158	                let gain = AudioLimiterModel.gain(
1159	                    reaching: target, steps: steps, peaks: peaks, ceiling: linearCeiling,
1160	                    releaseSeconds: masterReleaseSeconds, maxGain: maxGain)
1161	                capped = gain >= maxGain
1162	                wanted = 20 * log10(gain)
1163	            } else {
1164	                // Under one gating block, or no float read: the unlimited gain.
1165	                wanted = target - integrated
1166	                capped = wanted > maxGainDB
1167	            }
1168	            let rounded = min((wanted / gainStepDB).rounded() * gainStepDB, maxGainDB)
1169	            gainDB = rounded.isFinite ? rounded : 0
1170	        }
1171	        let shifted = measured.integratedLUFS.map { $0 + gainDB }
1172	        let lufs = modelled
1173	            ? AudioLimiterModel.integrated(
1174	                steps: steps, peaks: peaks, gain: pow(10, gainDB / 20), ceiling: linearCeiling,
1175	                releaseSeconds: masterReleaseSeconds) ?? shifted
1176	            : shifted
1177	        return ExportLoudness(
1178	            measured: measured, target: target, ceiling: ceiling, gainDB: gainDB,
1179	            integratedLUFS: lufs, cappedByGain: capped)
1180	    }
1181	
1182	    /// The one line every export reports: `"Peak −1.0 dBTP · −16.0 LUFS"`, with
1183	    /// `" · peaks limited by 8.6 dB"` when the master took 0.05 dB or more off.
1184	    var summary: String {
1185	        guard truePeakDBTP.isFinite else {
1186	            // −∞ is digital silence. Anything else non-finite is a mix
1187	            // carrying a non-finite sample, and calling THAT silent is the
1188	            // loudest lie this line could tell.
1189	            return truePeakDBTP == -.infinity
1190	                ? "Silent" : "Peak not measurable (a non-finite sample in the mix)"
1191	        }
1192	        let peak = "Peak \(Self.decibels(truePeakDBTP)) dBTP"
1193	        var measurement: String
1194	        if let integrated = integratedLUFS {
1195	            measurement = "\(peak) · \(Self.decibels(integrated)) LUFS"
1196	        } else {
1197	            // A programme shorter than one 400 ms gating block, or one whose
1198	            // every block fell under Γa. It has a peak and no loudness, and
1199	            // saying which is better than printing −∞.
1200	            measurement = "\(peak) · loudness not measurable"
1201	        }
1202	        if limitedDB >= 0.05 {
1203	            measurement += " · peaks limited by \(Self.decibels(limitedDB)) dB"
1204	        }
1205	        return measurement
1206	    }
1207	
1208	    /// One decimal, with the typographic minus the rest of the chrome uses.
1209	    private static func decibels(_ value: Double) -> String {
1210	        String(format: "%.1f", value).replacingOccurrences(of: "-", with: "−")
1211	    }
1212	}
