1	//! An HLG project's deliverables (spec §11 HD-5, HD-14): which picture an
2	//! export row writes — the HLG master, HDR10 (PQ) or the SDR version — and the
3	//! two refusals that keep a file from carrying a picture it cannot label.
4	//!
5	//! The vocabulary is three words, `hlg`, `pq` and `sdr`, spelled
6	//! `dynamic_range` both as an export override (`export_overrides.rs` reads it)
7	//! and as a recipe option (`recipe_options.rs`), because the two are one
8	//! decision seen from two sides: the export publishes its settings' `color` as
9	//! the recipe option of the key it draws, so the output pass the preview draws
10	//! for Show SDR Version is the one the file is written through.
11	//!
12	//! An SDR project is untouched by all of it: `deliverable` answers `None` for
13	//! every row there, so its settings carry no `color` and its recipes no
14	//! `dynamic_range`, and every SDR file and frame is the text and the bytes it
15	//! was.
16	
17	use crate::export_table::Preset;
18	use crate::model::{CanvasOutput, Project};
19	
20	/// The picture an HLG project's export or frame is drawn as (spec §11 HD-14).
21	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
22	pub enum DynamicRange {
23	    /// The working space itself, BT.2100 HLG: no output pass.
24	    Hlg,
25	    /// HDR10: the HLG display light at 1,000 cd/m² through ST 2084.
26	    Pq,
27	    /// The SDR version (spec §11 HD-4): the inverse of the lift with a
28	    /// shoulder above reference white, encoded Rec. 709.
29	    Sdr,
30	}
31	
32	impl DynamicRange {
33	    /// The word for `text`, or `None` for anything else.
34	    pub fn parse(text: &str) -> Option<DynamicRange> {
35	        match text {
36	            "hlg" => Some(DynamicRange::Hlg),
37	            "pq" => Some(DynamicRange::Pq),
38	            "sdr" => Some(DynamicRange::Sdr),
39	            _ => None,
40	        }
41	    }
42	
43	    /// The word as it is spelled in JSON.
44	    pub fn as_str(self) -> &'static str {
45	        match self {
46	            DynamicRange::Hlg => "hlg",
47	            DynamicRange::Pq => "pq",
48	            DynamicRange::Sdr => "sdr",
49	        }
50	    }
51	}
