53	/// The rows that carry an HDR picture (spec §11 HD-5, CX-14, CX-15, CX-16):
54	/// the six HDR rows, each 10-bit for an HDR picture (`vp9_webm` is 8-bit only
55	/// at `sdr`). Every other video row of an HLG project writes the SDR version.
56	pub(crate) const HDR_ROWS: [&str; 6] = [
57	    "hevc_10bit",
58	    "av1",
59	    "av1_webm",
60	    "vp9_webm",
61	    "prores_422",
62	    "prores_4444",
63	];
64	
65	impl Project {
66	    /// What `preset` writes for this project when `asked` was requested
67	    /// (spec §11 HD-14 (c)): `None` for an audio row and for every row of an
68	    /// SDR project (nothing to label), else the resolved picture. An audio row
69	    /// reads the argument and ignores it, as a bitrate on a GIF is; an SDR
70	    /// project takes `sdr` as nothing; `hlg` and `pq` are refused in an SDR
71	    /// project and on a row that is not 10-bit, each in its own sentence.
72	    pub(crate) fn deliverable(
73	        &self,
74	        preset: &Preset,
75	        asked: Option<DynamicRange>,
76	    ) -> Result<Option<DynamicRange>, String> {
77	        if !preset.video {
78	            return Ok(None);
79	        }
80	        let hdr_asked = asked.filter(|range| *range != DynamicRange::Sdr);
81	        if self.canvas.output != CanvasOutput::Hlg {
82	            return match hdr_asked {
83	                Some(range) => Err(format!(
84	                    "dynamic_range \"{}\" needs an HLG project; set_canvas output \"hlg\" first",
85	                    range.as_str()
86	                )),
87	                None => Ok(None),
88	            };
89	        }
90	        if HDR_ROWS.contains(&preset.id) {
91	            return Ok(Some(asked.unwrap_or(DynamicRange::Hlg)));
92	        }
93	        match hdr_asked {
94	            Some(range) => Err(format!(
95	                "{} is 8-bit and writes the SDR version; export dynamic_range \"{}\" as \
96	                 hevc_10bit, av1, av1_webm, vp9_webm, prores_422 or prores_4444",
97	                preset.id,
98	                range.as_str()
99	            )),
100	            None => Ok(Some(DynamicRange::Sdr)),
101	        }
102	    }
103	}
104	//! The stems an audio export writes beside its mix (spec §11 AU-108): which
105	//! timeline tracks each file holds and what it is called. Swift writes them
106	//! (`ExportStems.swift`); this answers only the grouping and the names, so
107	//! the sheet, the `export` tool and the tests read one list.
108	//!
109	//! The rules:
110	//!
111	//! - **Heard.** A timeline track is heard when the plan has an audio track
112	//!   labelled with it (`CompTrack::track`, AU-107 — so a track holding only
113	//!   pictures, or nothing, is not) and it is not `silenced` among the
114	//!   timeline's tracks (mute, solo). None heard is refused.
115	//! - **Grouping.** `tracks`: one stem per heard track. `names`: heard tracks
116	//!   whose trimmed names match case-insensitively are one stem, named by the
117	//!   first's spelling; an unnamed track is its own.
118	//! - **Order.** Timeline order of each stem's first track; a stem's tracks
119	//!   in timeline order.
120	//! - **Names.** The trimmed track name, else `Track N` (N = its index + 1,
121	//!   the header's label), with `/` and `:` replaced by `-`; a name equal
122	//!   case-insensitively to an earlier stem's gets ` (Track N)` of its first
123	//!   track, and one still equal to an earlier stem's then gets
124	//!   ` (Track N, 2)`, ` (Track N, 3)` and on, the first no earlier stem
125	//!   holds, so no two stems share a file.
126	
127	use std::collections::BTreeSet;
128	
129	use serde_json::{Map, Value};
130	
131	use crate::audio::silenced;
132	use crate::export_overrides::StemsMode;
133	use crate::model::Project;
134	
135	/// One stem: the file's name (without the mix's) and the timeline tracks
136	/// whose sound it holds.
137	#[derive(Debug, Clone, PartialEq, Eq)]
138	pub(crate) struct Stem {
139	    pub(crate) name: String,
140	    pub(crate) tracks: Vec<u32>,
141	}
142	
143	impl Stem {
144	    /// `{"name": …, "tracks": [ids]}`, the settings' `stems` entry.
145	    pub(crate) fn to_json(&self) -> Value {
146	        let mut out = Map::new();
147	        out.insert("name".to_string(), Value::from(self.name.clone()));
148	        let tracks = self.tracks.iter().map(|id| Value::from(*id)).collect();
149	        out.insert("tracks".to_string(), Value::Array(tracks));
150	        Value::Object(out)
151	    }
152	}
153	
154	/// A group while it is being gathered: its first track's index and the
155	/// spelling it is named by.
156	struct Group {
157	    first: usize,
158	    spelling: String,
159	    tracks: Vec<u32>,
160	}
161	
162	impl Project {
163	    /// The stems `mode` asks for, in order (spec §11 AU-108 (b), (c)), or
164	    /// the refusal when no track is heard.
165	    pub(crate) fn export_stems(&self, mode: StemsMode) -> Result<Vec<Stem>, String> {
166	        let labelled: BTreeSet<u32> = self.assign().audio.iter().map(|t| t.track).collect();
167	        let mut groups: Vec<Group> = Vec::new();
168	        for (index, track) in self.tracks.iter().enumerate() {
169	            if !labelled.contains(&track.id) || silenced(&self.tracks, track) {
170	                continue;
171	            }
172	            let trimmed = track.name.trim();
173	            let joins = match mode {
174	                StemsMode::Tracks => None,
175	                StemsMode::Names if trimmed.is_empty() => None,
176	                StemsMode::Names => groups
177	                    .iter_mut()
178	                    .find(|g| !g.spelling.is_empty() && same(&g.spelling, trimmed)),
179	            };
180	            match joins {
181	                Some(group) => group.tracks.push(track.id),
182	                None => groups.push(Group {
183	                    first: index,
184	                    spelling: trimmed.to_string(),
185	                    tracks: vec![track.id],
186	                }),
187	            }
188	        }
189	        if groups.is_empty() {
190	            return Err("stems: no track is heard, so there is no stem to write".to_string());
191	        }
192	        let mut stems: Vec<Stem> = Vec::with_capacity(groups.len());
193	        for group in groups {
194	            let label = format!("Track {}", group.first.saturating_add(1));
195	            let base = if group.spelling.is_empty() {
196	                label.clone()
197	            } else {
198	                group.spelling.replace(['/', ':'], "-")
199	            };
200	            let taken = |name: &str| stems.iter().any(|s| same(&s.name, name));
201	            let mut name = base.clone();
202	            if taken(&name) {
203	                name = format!("{base} ({label})");
204	            }
205	            let mut count: u32 = 2;
206	            while taken(&name) {
207	                name = format!("{base} ({label}, {count})");
208	                count = count.saturating_add(1);
209	            }
210	            stems.push(Stem {
211	                name,
212	                tracks: group.tracks,
213	            });
214	        }
215	        Ok(stems)
216	    }
217	}
