219	/// Two names the same but for case.
220	fn same(a: &str, b: &str) -> bool {
221	    a.to_lowercase() == b.to_lowercase()
222	}
223	//! The containers Frame Job writes (spec §7.8), and the four questions
224	//! each one answers about ITSELF: its extension, its UTI, whether a
225	//! leading index is worth rewriting, whether it can hold sound at all.
226	//!
227	//! Moved whole out of `export_table.rs` under the size rule (core/CLAUDE.md:
228	//! a module at ~600 lines gives something up BEFORE it takes anything on),
229	//! as codec-export C1's toll T1, a pure move. `export_table.rs` re-exports
230	//! [`Container`], so every `crate::export_table::Container` path holds.
231	
232	/// The containers Frame Job writes. Kept as an enum rather than a string so
233	/// the container, its UTI, its network-optimization default and whether it
234	/// can hold sound at all are decided in exactly one exhaustive place.
235	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
236	pub(crate) enum Container {
237	    Mov,
238	    Mp4,
239	    M4a,
240	    Wav,
241	    Aiff,
242	    Gif,
243	    Apng,
244	    /// WebM, written by the core's own writer (`webm_writer.rs`, spec §11
245	    /// CX-15), not by AVFoundation.
246	    Webm,
247	}
248	
249	impl Container {
250	    pub(crate) fn as_str(self) -> &'static str {
251	        match self {
252	            Container::Mov => "mov",
253	            Container::Mp4 => "mp4",
254	            Container::M4a => "m4a",
255	            Container::Wav => "wav",
256	            Container::Aiff => "aiff",
257	            Container::Gif => "gif",
258	            Container::Apng => "apng",
259	            Container::Webm => "webm",
260	        }
261	    }
262	
263	    /// The output file's UTI. On the AVFoundation path Swift passes this
264	    /// straight to `outputFileType`, whose raw values ARE UTIs; on the
265	    /// ImageIO path it is the destination type
266	    /// `CGImageDestinationCreateWithURL` takes. Either way it is what the
267	    /// save panel's content type and file extension are derived from, which
268	    /// is why the two image formats name a real UTI here rather than
269	    /// nothing — an export that could not tell the panel it writes a `.gif`
270	    /// would be worse off than one whose type string a session would
271	    /// reject, and a session is never built for them.
272	    ///
273	    /// An APNG is written to an ordinary PNG destination — the animation
274	    /// lives in `acTL`/`fcTL` chunks inside a file that is still a PNG — so
275	    /// its type identifier is PNG's, not one of its own.
276	    ///
277	    /// The two LPCM rows' identifiers are exactly `AVFileType.wav` and
278	    /// `AVFileType.aiff`'s raw values, which is what lets
279	    /// `Exporter.fileType(for:)` resolve them from this string alone
280	    /// rather than growing a container list of its own.
281	    pub(crate) fn file_type(self) -> &'static str {
282	        match self {
283	            Container::Mov => "com.apple.quicktime-movie",
284	            Container::Mp4 => "public.mpeg-4",
285	            Container::M4a => "com.apple.m4a-audio",
286	            Container::Wav => "com.microsoft.waveform-audio",
287	            Container::Aiff => "public.aiff-audio",
288	            Container::Gif => "com.compuserve.gif",
289	            Container::Apng => "public.png",
