610	/// What a cost is keyed by: the row, the AV1 speed, and the bit depth the encoder runs at.
611	struct ExportEncoderKey: Hashable {
612	    /// `av1`, `av1_webm`, `vp9_webm` or `vp9_alpha_webm`.
613	    let preset: String
614	    /// The AV1 rows' speed (`settings.encoderSpeed ?? .balanced`); nil on every other row.
615	    let speed: EncoderSpeed?
616	    /// 10 on `svt_av1` (CX-14: always 10-bit); on `libvpx` 10 for `hlg`/`pq` (Profile 2,
617	    /// CX-16 (3)), else 8.
618	    let bits: Int
619	
620	    init(preset: String, speed: EncoderSpeed?, bits: Int) {
621	        self.preset = preset
622	        self.speed = speed
623	        self.bits = bits
624	    }
625	
626	    /// The key of an export's settings; nil for an AVFoundation row (no `writer`).
627	    init?(settings: ExportSettings) {
628	        guard let writer = settings.writer else { return nil }
629	        let av1 = writer == "svt_av1"
630	        let deep = settings.dynamicRange == .hlg || settings.dynamicRange == .pq
631	        self.init(
632	            preset: settings.preset, speed: av1 ? settings.encoderSpeed ?? .balanced : nil,
633	            bits: av1 || deep ? 10 : 8)
634	    }
635	}
