911	    func measureLoudness(
912	        _ built: BuiltComposition, settings: ExportSettings
913	    ) -> ExportLoudness? {
914	        let tracks = built.composition.tracks(withMediaType: .audio)
915	        guard !tracks.isEmpty, let reader = try? AVAssetReader(asset: built.composition),
916	            let meter = LoudnessMeter(
917	                sampleRate: Exporter.measureSampleRate,
