932	        let subMixed = mixRead.isSubMixed
933	        var isFloat = true
934	        var output = Exporter.mixOutput(tracks, mix: built.audioMix, float: true)
935	        if subMixed {
936	            guard mixRead.add(to: reader) else { return nil }
937	        } else {
938	            if !reader.canAdd(output) {
939	                isFloat = false
940	                output = Exporter.mixOutput(tracks, mix: built.audioMix, float: false)
941	                guard reader.canAdd(output) else { return nil }
942	            }
