969	            setMeasureProgress(min(max(elapsed / seconds, 0), 1))
970	        }
971	        guard reader.status == .completed else { return nil }
972	        setMeasureProgress(1)
973	        let measuredSteps = isFloat ? stepMeter.finish() : (steps: [], peaks: [])
